function interact(id){const l=locs.find(x=>x.id===id);if(!l)return;state.x=l.x;state.z=l.z;moveTarget=null;activeLoc=id;renderUI();if(id==='home'){modal('Make yourself at home','Home is a soft place to land. Rest is free, but your rent comes around every week.',[
{title:'Sleep in',desc:'Recover your energy and ease the stress.',cost:'Free',action:()=>{state.energy=clamp(state.energy+42,0,100);state.stress=clamp(state.stress-16,0,100);advance(90);log('Slept in at home. Slow mornings are underrated.');renderUI();notify('Well rested.')}},
{title:'Tidy up',desc:'A little care for your space. Feel a bit more settled.',cost:'Free',action:()=>{advance(45);state.stress=clamp(state.stress-9,0,100);state.rep++;log('Tidied your apartment. It feels more like yours.');renderUI()}},
{title:'Review rent options',desc:'Your current place costs $425 a week.',cost:'Review'}
],'HOME · YOUR PLACE')}else if(id==='cafe'){modal('Corner café','Warm light, good coffee, and a familiar face behind the counter.',[
{title:'Grab a coffee',desc:'Take ten minutes. Feel more awake.',cost:'$6',action:()=>{if(spend(6)){state.energy=clamp(state.energy+12,0,100);state.stress=clamp(state.stress-3,0,100);advance(15);log('Coffee and a quiet moment at the corner café.');renderUI()}}},
{title:'Ask about work',desc:'Mara is usually happy to talk about openings.',cost:'Talk',action:()=>jobOffer()},
{title:'Pick up a shift',desc:'If you work here, you can get started right away.',cost:state.job?.company==='Corner café'?'Work':'Ask first',action:()=>state.job?.company==='Corner café'?doShift():jobOffer()}
],'CORNER CAFÉ · OPEN 7—6')}else if(id==='office'){modal('Civic Works','The local services office has a community employment desk and a quiet public lobby.',[
{title:'Browse career openings',desc:'Steadier work, professional development, room to grow.',cost:'Explore',action:()=>jobOffer()},
{title:'Pick up a shift',desc:'Your regular city services shift.',cost:state.job?.company==='Civic Works'?'Work':'Ask first',action:()=>state.job?.company==='Civic Works'?doShift():jobOffer()},
{title:'Use the public noticeboard',desc:'See what is happening around Northside.',cost:'Free',action:()=>{advance(15);state.rep++;log('Found the community noticeboard. The district is full of little opportunities.');notify('A few new leads to follow up.')}}
],'CIVIC WORKS · COMMUNITY SERVICES')}else if(id==='park'){modal('Maple Square','The leaves flicker over the benches. There is room to just be here.',[
{title:'Take a walk',desc:'Stretch your legs and clear your head.',cost:'Free',action:()=>{advance(30);state.energy=clamp(state.energy-4,0,100);state.stress=clamp(state.stress-14,0,100);log('Took a walk through Maple Square. The air helped.');renderUI();notify('A little more breathing room.')}},
{title:'Say hello to someone',desc:'A familiar face may turn into a real friend.',cost:'Connect',action:()=>talk()},
{title:'Community garden',desc:'Help out, meet your neighbors, maybe earn a little.',cost:'Gig board',action:()=>gigBoard()}
],'MAPLE SQUARE · PUBLIC PARK')}else if(id==='market'){modal('Sunday market','A lively little market. Fresh produce, handmade things, neighborhood chatter.',[
{title:'Buy something nice to eat',desc:'Good food can help you feel human again.',cost:'$14',action:()=>{if(spend(14)){state.energy=clamp(state.energy+16,0,100);state.stress=clamp(state.stress-5,0,100);advance(20);log('Picked up something good to eat at the market.');renderUI()}}},
{title:'Ask around for gigs',desc:'Vendors always need an extra pair of hands.',cost:'Browse',action:()=>gigBoard()},
{title:'Chat with a vendor',desc:'A small connection can open a door.',cost:'Free',action:()=>talk()}
],'SUNDAY MARKET · 8—2')}else if(id==='station'){modal('Northside transit','The bus stop connects the district to the rest of the city. Where might the day take you?',[
{title:'Head home',desc:'A quiet place to reset.',cost:'$2',action:()=>{if(spend(2)){state.x=-9;state.z=5;advance(15);renderUI()}}},
{title:'Ride across town',desc:'A change of scenery, a few new faces.',cost:'$4',action:()=>{if(spend(4)){state.relationships++;advance(35);log('Took the bus across town. You came back with a fresh perspective.');state.stress=clamp(state.stress-4,0,100);renderUI();notify('A little change of scenery.')}}},
{title:'Community noticeboard',desc:'Local leads and odd jobs.',cost:'Browse',action:()=>gigBoard()}
],'NORTHSIDE TRANSIT · ROUTE 7')}}

// A warm, walkable miniature neighborhood rendered with Three.js.
const canvas=$('#world'), viewport=$('#viewport');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.07;
const scene=new THREE.Scene();scene.background=new THREE.Color('#a5b99d');scene.fog=new THREE.Fog('#a5b99d',28,62);
const camera=new THREE.PerspectiveCamera(42,1,.1,100);camera.position.set(17,21,24);camera.lookAt(0,0,0);
scene.add(new THREE.HemisphereLight('#edf4df','#6c7459',2.2));const sun=new THREE.DirectionalLight('#fff0cb',3.3);sun.position.set(-12,22,10);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-24;sun.shadow.camera.right=24;sun.shadow.camera.top=24;sun.shadow.camera.bottom=-24;scene.add(sun);
const mat=(color,rough=.85)=>new THREE.MeshStandardMaterial({color,roughness:rough});const mats={grass:mat('#91a97f'),walk:mat('#c7c1a8'),road:mat('#69746c'),roof:mat('#a76d56'),wall:mat('#e2cfad'),brick:mat('#c09b7d'),glass:mat('#8fa9a1'),trunk:mat('#725640'),leaf:mat('#638461'),leaf2:mat('#789568'),white:mat('#f3e8cd'),dark:mat('#36433a'),yellow:mat('#e6bf74')};
const ground=new THREE.Mesh(new THREE.PlaneGeometry(90,90),mats.grass);ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;scene.add(ground);
function box(x,y,z,w,h,d,m,shadow=true){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);o.position.set(x,y+h/2,z);o.castShadow=shadow;o.receiveShadow=true;scene.add(o);return o}
// Roads, sidewalks, and lane dashes
box(0,-.045,0,31,.08,4.2,mats.road,false);box(0,-.035,-10,31,.08,2.4,mats.road,false);box(-13,-.03,0,2.6,.08,23,mats.road,false);box(13,-.03,0,2.6,.08,23,mats.road,false);
for(let x=-13;x<14;x+=3.4)box(x,.005,0,1.5,.018,.07,mats.yellow,false);for(let z=-9;z<11;z+=3.4)box(-13,.005,z,.07,.018,1.5,mats.yellow,false);
box(0,.01,2.5,31,.09,.55,mats.walk,false);box(0,.01,-2.5,31,.09,.55,mats.walk,false);box(0,.01,-8.55,31,.09,.48,mats.walk,false);
// House and main buildings
function house(x,z,w,d,color,roofColor=0){box(x,.02,z,w,3.8,d,mat(color));box(x,3.82,z,w+.45,.45,d+.45,roofColor?mat(roofColor):mats.roof);for(let wx=x-w/2+.8;wx<x+w/2-.45;wx+=1.35){box(wx,1.7,z-d/2-.035,.58,1.05,.08,mats.glass,false);box(wx,1.7,z-d/2-.09,.08,1.18,.06,mats.white,false);box(wx,1.7,z-d/2-.09,.66,.07,.06,mats.white,false)}box(x,1,z-d/2-.06,.75,1.8,.14,mats.brick,false);}
house(-9,6,5.1,4.3,'#dfc99e');house(-9,-7,5.1,3.4,'#c7b695');house(-2,-7,5,4,'#e0cba9','#8c8f73');
// Café and office front
box(-2,.04,-4,5.5,.18,4.1,mats.walk,false);box(-2,.2,-4,4.7,3.4,3.7,mat('#c98360'));box(-2,3.62,-4,5,.42,4,mat('#664e42'));box(-2,2.5,-5.9,3.8,1.18,.1,mats.glass,false);box(-2,3.38,-5.98,4,.2,.16,mats.white,false);box(-2,3.08,-6.08,1.7,.34,.1,mats.dark,false);box(-2,1.8,-6.04,.42,1.2,.12,mats.brick,false);
box(7,.04,-7,7,.18,5,mats.walk,false);box(7,.2,-7,6,5.6,4.4,mat('#b8c5b7'));box(7,3.12,-9.25,5.4,1.65,.12,mats.glass,false);box(7,5.9,-7,6.3,.35,4.7,mat('#657b75'));for(let x=5;x<10;x+=2)box(x,2.4,-9.34,.08,3.3,.1,mats.white,false);
// Market stalls
for(let i=0;i<3;i++){let x=9+i*2.35;box(x,.55,4,1.8,1.1,1.3,mat(i===1?'#ba795d':'#967d5d'));box(x,1.6,4,2.1,.18,1.6,mat(i===1?'#c86d57':'#d0ac68'));box(x,2.08,4,1.8,.7,.12,mat(i===1?'#d18b70':'#ece0bd'));for(let j=0;j<3;j++){const fruit=new THREE.Mesh(new THREE.SphereGeometry(.14,9,7),mat(['#cf6755','#dfa84b','#729b61'][j]));fruit.position.set(x-.5+j*.5,1.3,3.54);scene.add(fruit)}}
// Park paths & trees
box(3,.015,6,8,.06,1.2,mats.walk,false);box(4,.02,6,1,.07,6,mats.walk,false);
function tree(x,z,s=1){const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.13*s,.22*s,1.4*s,7),mats.trunk);trunk.position.set(x,.7*s,z);trunk.castShadow=true;scene.add(trunk);const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(.95*s,1),mat(Math.random()>.5?'#668561':'#7b9568'));crown.position.set(x,1.65*s,z);crown.castShadow=true;scene.add(crown);const c2=new THREE.Mesh(new THREE.IcosahedronGeometry(.62*s,1),mats.leaf2);c2.position.set(x+.38*s,1.9*s,z-.12*s);c2.castShadow=true;scene.add(c2)}
[[-2,7,1.1],[7,8,1.15],[1,9,.9],[7,3,.8],[-12,8,1],[-12,-2,.9],[11,-4,1.05],[-5,-10,.9],[12,-9,.9],[1,-10,1.1]].forEach(v=>tree(...v));
// Street fixtures, lamps, benches
function lamp(x,z){const pole=new THREE.Mesh(new THREE.CylinderGeometry(.045,.07,2.4,7),mats.dark);pole.position.set(x,1.2,z);pole.castShadow=true;scene.add(pole);box(x,2.4,z,.42,.12,.32,mats.yellow,false);const bulb=new THREE.PointLight('#ffe3a3',.25,4);bulb.position.set(x,2.25,z);scene.add(bulb)}
[[-6,-2],[5,-2],[10,0],[-10,2],[0,4]].forEach(v=>lamp(...v));
for(const x of [1,5]){box(x,.35,7,1.8,.22,.48,mat('#86664c'));box(x,.72,7.2,1.8,.16,.12,mat('#86664c'))}
// A little neighborhood signage
function sign(x,z,label,color){box(x,.7,z,.055,1.4,.055,mats.dark,false);const p=box(x,.2,z,1.25,.48,.08,mat(color),false);p.position.y=1.25;}
sign(-2,-6.04,'', '#f3e8cd');sign(7,-9.32,'','#e9dfc6');
// Person, shadows, and visual details
const player=new THREE.Group();scene.add(player);const body=new THREE.Mesh(new THREE.CapsuleGeometry(.34,.75,4,8),mat('#6a8b68'));body.position.y=.78;body.castShadow=true;player.add(body);const head=new THREE.Mesh(new THREE.SphereGeometry(.24,12,10),mat('#d6a77e'));head.position.y=1.48;head.castShadow=true;player.add(head);const hair=new THREE.Mesh(new THREE.SphereGeometry(.245,12,8,0,Math.PI*2,0,Math.PI*.52),mat('#4b382e'));hair.position.y=1.57;player.add(hair);const bag=new THREE.Mesh(new THREE.BoxGeometry(.32,.43,.2),mat('#bc8655'));bag.position.set(-.33,.95,.1);player.add(bag);player.position.set(state.x,0,state.z);
const people=[];function npc(x,z,color){const g=new THREE.Group();const b=new THREE.Mesh(new THREE.CapsuleGeometry(.26,.65,4,7),mat(color));b.position.y=.7;g.add(b);const h=new THREE.Mesh(new THREE.SphereGeometry(.2,10,8),mat('#c99973'));h.position.y=1.33;g.add(h);g.position.set(x,0,z);scene.add(g);people.push({g,x,z,phase:Math.random()*6});}
npc(-3,-3,'#bd946e');npc(3,5,'#758ca4');npc(9,3,'#b36d5d');npc(5,-5,'#88739d');npc(-8,3,'#d0ab63');
// Location labels and glowing markers rendered as in-world signposts.
const markers={};for(const l of locs){const m=new THREE.Mesh(new THREE.CylinderGeometry(.09,.09,.13,12),mat(l.color));m.position.set(l.x,.16,l.z);scene.add(m);const orb=new THREE.Mesh(new THREE.SphereGeometry(.17,12,10),new THREE.MeshStandardMaterial({color:l.color,emissive:l.color,emissiveIntensity:.42}));orb.position.set(l.x,1.55,l.z);scene.add(orb);markers[l.id]={m,orb,loc:l}}
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();let markerMeshes=Object.values(markers).map(v=>v.orb);
function resize(){const r=viewport.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(viewport);resize();
function setMove(x,z){moveTarget={x,z};activeLoc=null}
function onPointer(e){const r=canvas.getBoundingClientRect();pointer.x=(e.clientX-r.left)/r.width*2-1;pointer.y=-((e.clientY-r.top)/r.height)*2+1;raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObjects(markerMeshes)[0];if(hit){const l=Object.values(markers).find(v=>v.orb===hit.object)?.loc;if(l){interact(l.id);return}}const groundHits=raycaster.intersectObject(ground);if(groundHits.length){const p=groundHits[0].point;setMove(clamp(p.x,-13,13),clamp(p.z,-11,11))}}
canvas.addEventListener('pointerdown',onPointer);
const locContainer=$('#locations');locContainer.innerHTML=locs.map(l=>`<button class="locbtn" data-loc="${l.id}"><span class="locdot"></span>${l.name}<small>${l.sub}</small></button>`).join('');locContainer.querySelectorAll('button').forEach(b=>b.onclick=()=>interact(b.dataset.loc));
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys[k]=true;if(k==='e'){const n=nearestLoc();if(dist(n)<3.2)interact(n.id);else notify('Walk closer to a place, then press E.')}if(k==='escape')closeModal()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
let last=performance.now();function animate(now){requestAnimationFrame(animate);const dt=Math.min(.05,(now-last)/1000);last=now;let mx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),mz=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(moveTarget){mx=moveTarget.x-player.position.x;mz=moveTarget.z-player.position.z;if(Math.hypot(mx,mz)<.18)moveTarget=null}const len=Math.hypot(mx,mz);if(len>.03){mx/=Math.max(1,len);mz/=Math.max(1,len);player.position.x=clamp(player.position.x+mx*dt*4,-14,14);player.position.z=clamp(player.position.z+mz*dt*4,-12,12);player.rotation.y=Math.atan2(mx,mz);state.x=player.position.x;state.z=player.position.z;gameTime+=dt;if(gameTime>1.3){gameTime=0;advance(1);renderUI()}}people.forEach(p=>{p.g.position.y=Math.sin(now*.001+p.phase)*.025;p.g.rotation.y=Math.sin(now*.0005+p.phase)*.12});Object.values(markers).forEach(({orb,loc})=>{orb.position.y=1.5+Math.sin(now*.002+loc.x)*.12;const close=dist(loc)<2;orb.material.emissiveIntensity=close?.9:.35});const target=new THREE.Vector3(player.position.x+12,17,player.position.z+16);camera.position.lerp(target,.035);camera.lookAt(player.position.x,0,player.position.z);renderer.render(scene,camera)}requestAnimationFrame(animate);

