const $=s=>document.querySelector(s),clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),days=['MON','TUE','WED','THU','FRI','SAT','SUN'];
const locs=[{id:'home',name:'Your apartment',sub:'HOME · REST & RESET',x:-9,z:5,color:'#d4b68c'},{id:'cafe',name:'Corner café',sub:'HOSPITALITY · $',x:-2,z:-4,color:'#bc8262'},{id:'office',name:'Civic Works',sub:'CAREERS · $$',x:7,z:-7,color:'#8ba2a1'},{id:'park',name:'Maple Square',sub:'PEOPLE · FREE',x:3,z:6,color:'#8cac76'},{id:'market',name:'Sunday market',sub:'SHOP · FOOD',x:10,z:4,color:'#d9a95c'},{id:'station',name:'Transit stop',sub:'CITY · STORIES',x:-10,z:-7,color:'#798d9b'}];
const fresh=()=>({cash:850,energy:82,stress:18,day:1,hour:8,minute:0,job:null,x:-8,z:6,crime:0,arrested:0,relationships:0,skill:0,rep:0,worked:0,savingsGoal:false,apartment:true,feed:[]});let state;try{state={...fresh(),...JSON.parse(localStorage.getItem('daylight-save')||'{}')}}catch{state=fresh()}if(!Array.isArray(state.feed))state.feed=[];
let gameTime=0,keys={},toastTimer,moveTarget=null;function save(silent=false){localStorage.setItem('daylight-save',JSON.stringify(state));if(!silent)notify('Your life is saved.')}function notify(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}function log(text){state.feed.unshift({day:state.day,text});state.feed=state.feed.slice(0,4);renderUI()}function nearestLoc(){return locs.reduce((a,b)=>distance(b)<distance(a)?b:a,locs[0])}function distance(l){return Math.hypot(state.x-l.x,state.z-l.z)}function renderUI(){let weekday=days[(state.day-1)%7],year=Math.floor((state.day-1)/336)+1;$('#clock').innerHTML=`${weekday} · ${String(state.hour).padStart(2,'0')}:${String(state.minute).padStart(2,'0')}<small>SPRING · YEAR ${year}</small>`;$('#cash').textContent=Math.floor(state.cash).toLocaleString();$('#energyVal').textContent=Math.round(state.energy)+'%';$('#energyBar').style.width=state.energy+'%';$('#stressVal').textContent=Math.round(state.stress)+'%';$('#stressBar').style.width=state.stress+'%';$('#season').textContent=['SPRING','SUMMER','AUTUMN','WINTER'][Math.floor(((state.day-1)%336)/84)];$('#weather').textContent=['☀ CLEAR SKIES','☁ SOFT CLOUDS','✦ GOOD DAY OUT'][state.day%3];$('#cashflow').innerHTML=`<span class="income">↑ $${state.worked} this week</span> · Rent due in ${7-((state.day-1)%7)} days`;$('#jobTag').textContent=state.job?state.job.level:'LOOKING';$('#jobName').textContent=state.job?state.job.name:'Between things';$('#jobMeta').textContent=state.job?`${state.job.company} · ${state.job.schedule}`:'Find your first opportunity';$('#careerBar').style.width=state.job?Math.min(100,12+state.rep*8)+'%':'12%';$('#careerText').textContent=state.job?`Reputation ${state.rep} · skill ${state.skill}`:'Career progress';$('#payText').textContent=state.job?`$${state.job.pay}/shift`:'No income yet';let goal=state.job?state.cash>=1000?'Build a buffer: keep <strong>$2,000</strong> saved, and look after yourself.':'Get your footing: build an emergency fund of <strong>$1,000</strong>.':'Get your footing: find work and keep <strong>$1,000</strong> in your account.';if(state.arrested)goal=`You have ${state.arrested} day${state.arrested===1?'':'s'} left on your sentence. Keep steady; tomorrow comes.`;if(state.cash<0)goal='Your balance is overdrawn. Find a shift, ask for help, and make a plan.';$('#goalText').innerHTML=goal;$('#goalNum').textContent=state.arrested?'RESET & REBUILD':'GOAL 0'+(state.job?2:1);$('#feed').innerHTML=state.feed.length?state.feed.map(f=>`<div class="feeditem"><time>D${f.day}</time><div>${f.text}</div></div>`).join(''):'<div class="feeditem"><time>NOW</time><div>A fresh start in Northside. <b>Make it yours.</b></div></div>';$('#nearby').innerHTML=`<b>●</b> ${nearestLoc().name.toLowerCase()} nearby`;$('#placeTitle').textContent=nearestLoc().id==='home'?'A new day.':nearestLoc().name;$('#placeText').textContent=nearestLoc().id==='home'?'Your story starts right here. Where to?':'A good place to spend a little time.'}
function addCash(n){state.cash=Math.round((state.cash+n)*100)/100}function spend(n){if(state.cash<n){notify('Not quite enough in your account.');return false}addCash(-n);return true}
function advance(min=30){const before=state.day;state.minute+=min;while(state.minute>=60){state.minute-=60;state.hour++}while(state.hour>=24){state.hour-=24;state.day++}const passed=state.day-before;if(passed){state.energy=clamp(state.energy+22*passed,0,100);state.stress=clamp(state.stress-12*passed,0,100);for(let d=0;d<passed;d++){if((state.day-d-1)%7===0&&(state.day-d)!==1){addCash(state.apartment?-425:0);if(state.apartment)log('Rent paid: <b>−$425</b>. Keep an eye on the budget.');if(state.job){addCash(60);log('A small weekly transit credit arrived: <b>+$60</b>.')}}}if(state.arrested)state.arrested=Math.max(0,state.arrested-passed);renderUI()}}
function closeModal(){$('#modalback').classList.remove('open')}function modal(title,copy,choices,eyebrow='NORTHSIDE',note=''){ $('#modalTitle').textContent=title;$('#modalCopy').innerHTML=copy;$('#modalEyebrow').textContent=eyebrow;$('#modalNote').textContent=note;$('#choices').innerHTML='';choices.forEach(c=>{const b=document.createElement('button');b.className='choice'+(c.danger?' danger':'');b.innerHTML=`<span><b>${c.title}</b><small>${c.desc}</small></span><em>${c.cost||''}</em>`;b.onclick=()=>{if(c.action)c.action();if(c.close!==false)closeModal()};$('#choices').append(b)});$('#modalback').classList.add('open')}
function takeJob(name,company,pay,schedule){state.job={name,company,pay,schedule,level:'STARTER'};state.rep=Math.max(state.rep,1);log(`You started as a <b>${name}</b> at ${company}.`);notify('New chapter: you have a job!');renderUI()}
function jobOffer(){modal('A couple of openings','Mara at the café says they are looking for reliable people. Civic Works has an entry-level role too. Pick what fits you.',[{title:'Café crew',desc:'Friendly shifts, learn on the job. A good first step.',cost:'$95 / shift',action:()=>takeJob('Café crew','Corner café',95,'Flexible · 4 hours')},{title:'City services assistant',desc:'Steady schedule, room to grow. Requires a short interview.',cost:'$145 / shift',action:()=>takeJob('Services assistant','Civic Works',145,'Weekdays · 5 hours')},{title:'Browse gig board',desc:'One-off neighborhood tasks, no commitment.',cost:'Varies',action:()=>gigBoard()}],'WORK & PURPOSE','All roles are fictional. Your choices shape the kind of week you have.')}
function gigBoard(){modal('Northside gig board','A few neighbors have posted small jobs. Nothing glamorous, but it all adds up.',[{title:'Help Jo carry boxes',desc:'A quick favor across the square. Take your time.',cost:'+$48',action:()=>{advance(90);state.energy=clamp(state.energy-14,0,100);addCash(48);state.rep++;log('Helped a neighbor move. <b>+$48</b> and a new connection.');renderUI()}},{title:'Water the community garden',desc:'Quiet work, good for your head.',cost:'+$35',action:()=>{advance(60);state.energy=clamp(state.energy-7,0,100);state.stress=clamp(state.stress-8,0,100);addCash(35);log('Spent an hour in the garden. <b>+$35</b>, and felt lighter.');renderUI()}},{title:'Not today',desc:'You can always come back later.'}],'COMMUNITY BOARD')}

function doShift(){if(state.arrested){notify('You need to finish your sentence first.');return}if(!state.job){jobOffer();return}if(state.energy<18){notify('You are too tired for a shift. Get some rest first.');return}const pay=state.job.pay+state.skill*8;advance(240);addCash(pay);state.energy=clamp(state.energy-28,0,100);state.stress=clamp(state.stress+11,0,100);state.skill++;state.worked+=pay;state.rep++;if(state.rep>=6&&state.job.level==='STARTER'){state.job.level='REGULAR';state.job.pay+=25;log(`Your reliability paid off: promoted to <b>REGULAR</b> at ${state.job.company}.`)}else log(`Finished a shift at ${state.job.company}. <b>+$${pay}</b> · skill ${state.skill}.`);renderUI();notify(`Shift complete · +$${pay}`)}
function talk(){const people=[['Mara','Corner café','Mara remembers your name. “You do not have to have it all figured out. Just keep showing up.”'],['Dev','Maple Square','Dev is sketching the old clock tower. “This city is nicer when you know a few people in it.”'],['Sam','Sunday market','Sam runs the fruit stand and has strong opinions about pears. You end up swapping stories.']];const p=people[(state.relationships+state.day)%people.length];modal(`Catch up with ${p[0]}`,p[2],[{title:'Listen and share a little',desc:'A small conversation can make a day.',cost:'+ connection',action:()=>{advance(25);state.relationships++;state.stress=clamp(state.stress-6,0,100);if(state.relationships%3===0)state.rep++;log(`Had a good conversation with <b>${p[0]}</b>. Connections matter.`);renderUI();notify('Connection made.')}},{title:'Ask about opportunities',desc:'People sometimes know who is hiring.',cost:'Free',action:()=>{advance(15);state.relationships++;if(!state.job)takeJob('Café crew','Corner café',95,'Flexible · 4 hours');else log(`${p[0]} shared a neighborhood tip. A little more connected.`);renderUI()}}],'NEIGHBORHOOD · '+p[1].toUpperCase())}
function rest(){if(state.arrested){notify('Rest is all you can do right now.');advance(60);return}state.energy=clamp(state.energy+24,0,100);state.stress=clamp(state.stress-12,0,100);advance(30);log('Took a proper breather. A little space to reset.');renderUI();notify('You feel a bit more rested.')}
function phone(){modal('A few things on your mind','Your phone is full of little life admin. What do you want to take care of?',[{title:'Check your budget',desc:`$${Math.floor(state.cash)} available · rent $425 each week.`,cost:'Look'},{title:'Browse local classifieds',desc:'A neighbor is offering a cheap bike tune-up, or there are small gigs.',cost:'$18',action:()=>{if(spend(18)){state.energy=clamp(state.energy+8,0,100);log('Booked a bike tune-up. The ride is easier now.');renderUI()}}},{title:'Set a savings intention',desc:'Make a little plan for the next few days.',cost:'Free',action:()=>{state.savingsGoal=true;log('Set a savings intention. Small choices add up.');notify('Intention set. You got this.')}}],'YOUR PHONE','Take care of yourself; there is no perfect way to live a life.')}
function crime(){if(state.arrested){notify('You cannot make that choice while serving a sentence.');return}modal('A risky shortcut?','Someone offers a vague, off-the-books errand. The money sounds good, but it could hurt someone, cost you your job, or bring serious legal trouble. There is no clean guarantee.',[{title:'Walk away',desc:'There are better ways to get through a hard week.',cost:'Stay safe',action:()=>{state.stress=clamp(state.stress-3,0,100);log('You walked away from a risky offer and chose a steadier path.')}},{title:'Take the risk',desc:'An abstract, fictional choice with unpredictable consequences.',cost:'Risky',danger:true,action:()=>{advance(90);state.stress=clamp(state.stress+18,0,100);const roll=Math.random();if(roll<.56){const gain=90+Math.floor(Math.random()*111);addCash(gain);state.crime++;log(`The errand paid <b>$${gain}</b>, but the anxiety stayed with you.`);notify(`+$${gain} · watch your stress`)}else if(roll<.82){addCash(-120);state.stress=clamp(state.stress+20,0,100);log('The errand went badly. <b>$120 fine</b> and a hard lesson.');notify('You were fined. Make a different plan.')}else{const sentence=2+Math.floor(Math.random()*3);state.arrested=sentence;state.cash=Math.max(0,state.cash-80);state.job=null;state.x=-10;state.z=-7;player.position.set(state.x,0,state.z);log(`You were arrested. Your fictional sentence is <b>${sentence} days</b>; your job is gone. You can start again.`);notify(`Sentence: ${sentence} days · take time to reset`)}renderUI()}}],'A HARD CHOICE','This is a fictional life sim. It does not describe real-world methods of crime.')}

