function renderLog(){const el=document.getElementById('logList');if(!el)return;el.innerHTML=(state.logs.length?state.logs:[{text:'A new week, a fresh start. Your story begins here.',day:state.day,minute:state.minute}]).map(x=>`<div class="log-entry"><time>D${x.day} · ${String(Math.floor(x.minute/60)%24).padStart(2,'0')}:${String(x.minute%60).padStart(2,'0')}</time>${x.text}</div>`).join('')}
function renderUI(){document.getElementById('cash').textContent=`$${Math.floor(state.cash)}`;document.getElementById('cashMeter').style.width=`${clamp(state.cash/10,0,100)}%`;document.getElementById('rentDue').textContent=state.rentIn===1?'tomorrow':`${state.rentIn} days`;for(const [key,label] of [['energy','energy'],['wellbeing','wellbeing'],['stress','stress']]){document.getElementById(`${label}Text`).textContent=`${state[key]} / 100`;document.getElementById(`${label}Bar`).style.width=`${state[key]}%`}document.getElementById('skillNum').textContent=state.skill;document.getElementById('friendNum').textContent=state.relationships;document.getElementById('dayLabel').innerHTML=`${['SUNDAY','MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY'][state.day%7]} <span>· ${formatTime()}</span>`;document.getElementById('clock').textContent=formatTime();document.getElementById('jobTitle').textContent=state.job?state.job.title:'Between jobs';document.getElementById('jobBadge').textContent=state.job?state.job.level:'OPEN';document.getElementById('jobDesc').textContent=state.job?`${state.job.company} · $${state.job.pay}+ per shift`:'Find a first shift or ask a neighbor about openings.';document.getElementById('whereLabel').innerHTML=`⌖ &nbsp; ${places.find(p=>p[0]===state.place)?.[2]||'Your apartment'}`;document.getElementById('playerName').textContent=state.arrested?'Alex Rivera · taking a pause':'Alex Rivera';renderLog();saveGame()}
function modal(title,description,choices,kicker='A DAY IN MAPLEWOOD',note=''){const root=document.getElementById('modalRoot');root.innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal"><div class="modal-top"><div class="eyebrow">${kicker}</div><button class="close" onclick="closeModal()">×</button></div><h2>${title}</h2><p>${description}</p><div class="choices">${choices.map((c,i)=>`<button class="choice ${c.danger?'danger':''}" onclick="choose(${i})"><span><b>${c.title}</b><small>${c.desc||''}</small></span><em>${c.cost||''}</em></button>`).join('')}</div>${note?`<p style="margin:12px 0 0;font-size:10px">${note}</p>`:''}</section></div>`;window._choices=choices}
function choose(i){const c=window._choices?.[i];closeModal();if(c?.action)c.action()}
function closeModal(){document.getElementById('modalRoot').innerHTML=''}
function go(id){selected=id;state.place=id;const found=places.find(p=>p[0]===id);document.querySelectorAll('.place').forEach(el=>el.classList.toggle('active',el.dataset.id===id));if(player){const target=found?.pos||new THREE.Vector3(-10,0,-7);player.position.x=target.x;player.position.z=target.z;state.x=target.x;state.z=target.z}renderUI();if(id==='cafe')modal('Corner café','Warm bread, familiar faces, and a little work if you need it.',[{title:'Order a coffee',desc:'A small treat and a quiet moment.',cost:'$6',action:()=>{if(spend(6)){state.stress=clamp(state.stress-7,0,100);advance(15);log('Enjoyed a coffee at the Corner café.');renderUI()}}},{title:'Ask about a shift',desc:'The café sometimes needs an extra pair of hands.',cost:'Free',action:()=>jobOffer()}],'NEIGHBORHOOD · CORNER CAFÉ');else if(id==='square')modal('Maple Square','The old clock tower keeps imperfect time. Someone is walking a very enthusiastic dog.',[{title:'Take a peaceful walk',desc:'A little fresh air and movement.',cost:'Free',action:()=>{state.wellbeing=clamp(state.wellbeing+8,0,100);state.stress=clamp(state.stress-7,0,100);advance(25);log('Took a calming walk through Maple Square.');renderUI()}},{title:'Say hello to someone',desc:'A friendly chat can brighten the day.',cost:'Free',action:talk}],'NEIGHBORHOOD · MAPLE SQUARE');else if(id==='market')modal('Sunday market','Seasonal fruit, handmade bits, and neighbors catching up.',[{title:'Pick up groceries',desc:'Basic food for the week; helps you feel better.',cost:'$32',action:()=>{if(spend(32)){state.wellbeing=clamp(state.wellbeing+13,0,100);advance(20);log('Bought groceries at the Sunday market.');renderUI()}}},{title:'Browse a small gig',desc:'Ask around for a neighborhood task.',cost:'Free',action:gig}],'NEIGHBORHOOD · SUNDAY MARKET');else if(id==='library')modal('Little free library','A cozy reading room, open to everyone.',[{title:'Read and learn',desc:'Build your work skill and lower your stress.',cost:'Free',action:()=>{advance(45);state.skill++;state.stress=clamp(state.stress-8,0,100);log('Spent a little time learning at the library. Skill improved.');renderUI();notify('Skill improved.')}},{title:'Rest in the quiet',desc:'Take a moment to breathe.',cost:'Free',action:rest}],'NEIGHBORHOOD · LITTLE FREE LIBRARY')}
function jobOffer(){if(state.arrested){notify('Focus on getting through today.');return}const jobs=[{title:'Café crew',company:'Corner café',pay:95,schedule:'Flexible · 4 hours'},{title:'Market helper',company:'Sunday market',pay:110,schedule:'Mornings · 4 hours'},{title:'Library assistant',company:'Little free library',pay:85,schedule:'Quiet shifts · 3 hours'}];modal('A few local openings','A steady shift can make the week feel a little easier.',jobs.map(j=>({title:j.title,desc:`${j.company} · ${j.schedule}`,cost:`$${j.pay}/shift`,action:()=>takeJob(j.title,j.company,j.pay,j.schedule)})).concat([{title:'Maybe later',desc:'You can ask again any time.',cost:'Close'}]),'WORK & COMMUNITY')}
