function gig(){if(state.arrested){notify('Rest and take care of yourself for now.');return}modal('A small neighborhood gig','Help someone out with a simple task. No special experience needed.',[{title:'Water plants for a neighbor',desc:'A gentle stroll and a little care.',cost:'+$48',action:()=>{advance(60);addCash(48);state.energy=clamp(state.energy-10,0,100);state.wellbeing=clamp(state.wellbeing+3,0,100);log('Watered plants for a neighbor and earned <b>$48</b>.');renderUI();notify('Gig complete · +$48')}},{title:'Help at the market',desc:'A few hours setting up and chatting.',cost:'+$70',action:()=>{if(state.energy<20){notify('You need a little rest before that.');return}advance(90);addCash(70);state.energy=clamp(state.energy-16,0,100);state.relationships++;log('Helped at the neighborhood market and earned <b>$70</b>.');renderUI();notify('Gig complete · +$70')} }],'GIG BOARD')}

