function crime(){if(state.arrested){notify('You cannot make that choice while serving a sentence.');return}modal('A risky shortcut?','Someone offers a vague, off-the-books errand. The money sounds good, but it could hurt someone, cost you your job, or bring serious legal trouble. There is no clean guarantee.',[{title:'Walk away',desc:'There are better ways to get through a hard week.',cost:'Stay safe',action:()=>{state.stress=clamp(state.stress-3,0,100);log('You walked away from a risky offer and chose a steadier path.');renderUI()}},{title:'Take the risk',desc:'An abstract, fictional choice with unpredictable consequences.',cost:'Risky',danger:true,action:()=>{advance(90);state.stress=clamp(state.stress+18,0,100);const roll=Math.random();if(roll<.56){const gain=90+Math.floor(Math.random()*111);addCash(gain);state.crime++;log(`The errand paid <b>$${gain}</b>, but the anxiety stayed with you.`);notify(`+$${gain} · watch your stress`)}else if(roll<.82){addCash(-120);state.stress=clamp(state.stress+20,0,100);log('The errand went badly. <b>$120 fine</b> and a hard lesson.');notify('You were fined. Make a different plan.')}else{const sentence=2+Math.floor(Math.random()*3);state.arrested=sentence;state.cash=Math.max(0,state.cash-80);state.job=null;state.x=-10;state.z=-7;state.place='home';if(player)player.position.set(state.x,0,state.z);log(`You were arrested. Your fictional sentence is <b>${sentence} days</b>; your job is gone. You can start again.`);notify(`Sentence: ${sentence} days · take time to reset`)}renderUI()}}],'A HARD CHOICE','This is a fictional life sim. It does not describe real-world methods of crime.')}
