kground:#13252280;z-index:10;display:grid;place-items:center;padding:18px;backdrop-filter:blur(4px)}.modal{width:min(480px,100%);background:var(--card);border:1px solid #fff;border-radius:22px;padding:23px;box-shadow:0 24px 80px #10231e55;animation:pop .18s ease-out}@keyframes pop{from{transform:translateY(7px) scale(.98);opacity:0}to{transform:none;opacity:1}}.modal-top{display:flex;justify-content:space-between}.modal h2{font:600 26px Fraunces,serif;margin:7px 0}.modal p{color:#66726a;font-size:12px;line-height:1.6;margin:0 0 15px}.close{border:0;background:#f0efe8;border-radius:50%;width:31px;height:31px;font-size:17px}.choices{display:grid;gap:8px}.choice{width:100%;display:flex;justify-content:space-between;align-items:center;text-align:left;border:1px solid var(--line);background:#fffefa;border-radius:13px;padding:12px}.choice:hover{border-color:#b8c9b2;background:#f1f4eb}.choice.danger:hover{border-color:#df9d8b;background:#fbefeb}.choice b{display:block;font-size:12px}.choice small{display:block;color:var(--muted);font-size:10px;margin-top:3px}.choice em{font-style:normal;font-size:10px;color:var(--green);font-weight:800;margin-left:8px;white-space:nowrap}.toast{position:fixed;z-index:20;bottom:22px;left:50%;transform:translate(-50%,20px);padding:11px 16px;background:#193a32;color:#fff;border-radius:12px;font-size:12px;opacity:0;transition:.2s;pointer-events:none;box-shadow:0 8px 25px #16262030}.toast.show{opacity:1;transform:translate(-50%,0)}.footerhint{font-size:10px;color:#89928b;text-align:center;padding:12px 0 0}.hidden{display:none!important}
